    const size=directory.reduce((n,b)=>n+b.length,0),end=header(22),v=end.view;v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);const all=[...entries,...directory,end.bytes],result=new Uint8Array(offset+size+22);let p=0;for(const b of all){result.set(b,p);p+=b.length;}return result;
